import React from 'react';
import { phonePlans } from '../config/phonePlanConfig';

/**
 * PhoneSalesFilterForm
 * 1) 카테고리 → 2) 요금제 → 3) 데이터 순서
 * 요금제 선택 시 해당 요금제의 데이터만 표시
 */
export default function PhoneSalesFilterForm({ values, onFilterChange }) {
  // 1) 카테고리 옵션 (전체 포함)
  const categoryOptions = [
    { value: '', label: '전체' },
    ...Array.from(new Set(phonePlans.map(p => p.category))).map(cat => ({ value: cat, label: cat }))
  ];

  // 2) 요금제 옵션 (category 필터링 기준)
  const planOptions = [
    { value: '', label: '전체' },
    ...phonePlans
      .filter(p => !values.category || p.category === values.category)
      .map(p => ({ value: p.id, label: `${p.name} (${p.monthlyFee.toLocaleString()}원)` }))
  ];

  // 3) 데이터 옵션: 요금제 선택 시 해당 요금제 데이터만 표시
  const selectedPlan = phonePlans.find(p => p.id === values.planId);
  const dataOptions = selectedPlan
    ? [{ value: selectedPlan.data, label: selectedPlan.data }]
    : [
        { value: '', label: '전체' },
        ...Array.from(
          new Set(
            phonePlans
              .filter(p => !values.category || p.category === values.category)
              .map(p => p.data)
          )
        ).map(d => ({ value: d, label: d }))
      ];

  return (
    <div className="mb-6 space-y-4">
      {/* 카테고리 */}
      <Select
        label="카테고리"
        name="category"
        options={categoryOptions}
        value={values.category}
        onChange={onFilterChange}
      />

      {/* 요금제 */}
      <Select
        label="요금제"
        name="planId"
        options={planOptions}
        value={values.planId}
        onChange={onFilterChange}
      />

      {/* 데이터: 요금제 선택 시 단일 옵션만 */}
      <Select
        label="데이터"
        name="dataFilter"
        options={dataOptions}
        value={values.dataFilter}
        onChange={onFilterChange}
      />
    </div>
  );
}

function Select({ label, name, options, value, onChange }) {
  return (
    <div>
      <label className="block text-sm font-medium mb-1">{label}</label>
      <select
        name={name}
        value={value}
        onChange={e => onChange(name, e.target.value)}
        className="w-full border p-2 rounded-md"
      >
        {options.map(opt => (
          <option key={opt.value} value={opt.value}>{opt.label}</option>
        ))}
      </select>
    </div>
  );
}
