import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import PhoneSalesFilterForm from './PhoneSalesFilterForm';
import PhoneSalesInputForm from './PhoneSalesInputForm';
import PhoneSalesResult from './PhoneSalesResult';
import { phonePlans } from '../config/phonePlanConfig';
import SaveConsultationButton from '../components/SaveConsultationButton';  // 상담 저장 및 공유 버튼 컴포넌트

export default function PhoneSalesCalculator() {
  const navigate = useNavigate();
  const [values, setValues] = useState({
    dataFilter: '',
    category: '',
    planId: '',
    planCost: 0,
    devicePrice: 0,
    partialPayment: 0,
    subsidyAmount: 0,
    discountType: '',
    installments: 24,
    pensionApply: '' // 기초연금 수급 여부
  });

  const [results, setResults] = useState(null);
  const [recommendedDiscount, setRecommendedDiscount] = useState('');
  const monthlyRate = 0.059 / 12;

  const handleFilterChange = (name, value) => {
    setValues(prev => {
      const next = { ...prev, [name]: value };
      if (name === 'planId') {
        const plan = phonePlans.find(p => p.id === value) || {};
        next.planCost = plan.monthlyFee || 0;
      }
      if (name === 'category' || name === 'dataFilter') {
        next.planId = '';
        next.planCost = 0;
      }
      return next;
    });
    setResults(null);
    setRecommendedDiscount('');
  };

  // 필드 변경 핸들러: name, value 쌍으로 호출
  const handleChange = (name, value) => {
    setValues(prev => ({
      ...prev,
      [name]: ['installments', 'partialPayment', 'subsidyAmount', 'devicePrice'].includes(name)
        ? Number(value)
        : value
    }));
    setResults(null);
    setRecommendedDiscount('');
  };

  const isSenior = values.category === '5G 시니어 (만 65세 이상)';
  const hasPension = values.pensionApply === 'yes';

  const canCalc =
    values.planCost > 0 &&
    values.devicePrice > 0 &&
    values.discountType !== '' &&
    (!isSenior || values.pensionApply !== '');

  const handleCalculate = () => {
    if (!canCalc) return;
    const { planCost, devicePrice, partialPayment, subsidyAmount, discountType, installments } = values;

    // 기초연금 할인액 (시니어 & 적용 시 최대 12,100원)
    const pensionDiscount = isSenior && hasPension ? Math.min(planCost * 0.5, 12100) : 0;

    // 단말 원금 계산
    const basePrincipal = devicePrice - partialPayment;
    const principalSubsidy = basePrincipal - subsidyAmount;

    // 단말 할부 계산
    const deviceContract = installments > 0
      ? Math.ceil((basePrincipal * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;
    const deviceSubsidyCost = installments > 0
      ? Math.ceil((principalSubsidy * monthlyRate) / (1 - Math.pow(1 + monthlyRate, -installments)))
      : 0;

    // 시나리오별 총액
    // 1) 계약할인 시나리오: 요금 25% 할인 + 단말 할부 - 기초연금 할인
    const scenarioContractTotal = planCost * 0.75 + deviceContract - pensionDiscount;
    // 2) 공시지원금 시나리오: 요금 그대로 + 단말 공시지원금 할부 - 기초연금 할인
    const scenarioSubsidyTotal = planCost + deviceSubsidyCost - pensionDiscount;

    // 사용자 선택 결과
    const totalPayment = discountType === 'contract'
      ? scenarioContractTotal
      : scenarioSubsidyTotal;
    const deviceInstallment = discountType === 'contract'
      ? deviceContract
      : deviceSubsidyCost;

    // 절감액 및 추천 할인
    const savings = discountType === 'contract'
      ? scenarioSubsidyTotal - scenarioContractTotal
      : scenarioContractTotal - scenarioSubsidyTotal;
    const recommended = scenarioContractTotal < scenarioSubsidyTotal
      ? '요금할인'
      : '공시 지원금';

    setResults({ monthlyPlanCost: planCost, deviceInstallment, totalPayment, savings, appliedPensionDiscount: pensionDiscount });
    setRecommendedDiscount(recommended);
  };

  return (
    <div className="flex flex-col items-center min-h-screen bg-gray-50 p-4">
      <div className="w-full max-w-lg bg-white shadow rounded-2xl p-6 mb-4">
        <h2 className="text-2xl font-bold mb-6 text-center">KT 핸드폰 상담 계산기</h2>
        <p className="mt-2 text-base font-bold text-red-500">
          주의! 본 견적은 가견적이오니, 정확한 견적은 필히 추가 확인 바랍니다.
        </p>

        <PhoneSalesFilterForm values={values} onFilterChange={handleFilterChange} />
        <PhoneSalesInputForm
          values={values}
          onChange={handleChange}
          others={phonePlans.find(p => p.id === values.planId)?.others}
          recommendedDiscount={recommendedDiscount}
        />

        <button
          onClick={handleCalculate}
          disabled={!canCalc}
          className={`w-full py-2 rounded-md mb-4 transition ${canCalc
            ? 'bg-blue-500 text-white hover:bg-blue-600'
            : 'bg-gray-300 text-gray-600 cursor-not-allowed'}`}
        >
          계산하기
        </button>
        {/* 결과 */}
        {results && (
          <>
            <PhoneSalesResult
              monthlyPlanCost={results.monthlyPlanCost}
              deviceInstallment={results.deviceInstallment}
              totalPayment={results.totalPayment}
              savings={results.savings}
              appliedPensionDiscount={results.appliedPensionDiscount}
              discountType={values.discountType}
              pensionApply={values.pensionApply}
            />
            <div className="mt-4">
              <SaveConsultationButton formData={values} />
            </div>
          </>
        )}

        <button
          onClick={() => navigate('/')}
          className="w-full bg-gray-200 text-gray-700 py-2 rounded hover:bg-gray-300 transition"
        >
          메인 메뉴로 돌아가기
        </button>
      </div>
    </div>
  );
}
