/**
 * key 는 consultation-{timestamp} 형태로, 각 상담을 개별 저장
 */
const STORAGE_KEY_PREFIX = 'consultation-';

export function saveConsultationLocal(data) {
  try {
    const timestamp = Date.now();
    const key = STORAGE_KEY_PREFIX + timestamp;
    const json = JSON.stringify({ ...data, savedAt: timestamp });
    localStorage.setItem(key, json);
    return true;
  } catch (err) {
    console.error('LocalStorage save error:', err);
    return false;
  }
}

/**
 * 저장된 모든 상담 목록 불러오기
 */
export function loadAllConsultationsLocal() {
  const consultations = [];
  for (let i = 0; i < localStorage.length; i++) {
    const key = localStorage.key(i);
    if (key.startsWith(STORAGE_KEY_PREFIX)) {
      try {
        const obj = JSON.parse(localStorage.getItem(key));
        consultations.push({ key, ...obj });
      } catch {}
    }
  }
  // 최신순 정렬
  return consultations.sort((a, b) => b.savedAt - a.savedAt);
}

/**
 * 특정 상담 삭제
 */
export function removeConsultationLocal(key) {
  localStorage.removeItem(key);
}
