// src/calculators/PhoneSalesInputForm.jsx
import React from 'react';

export default function PhoneSalesInputForm({
  values,
  onChange,
  others,
  recommendedDiscount,
}) {
  return (
    <>
      {/* 단말기 출고가 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">단말기 출고가</label>
        <input
          type="number"
          name="devicePrice"
          value={values.devicePrice || ''}
          onChange={e => onChange('devicePrice', Number(e.target.value))}
          className="w-full border p-2 rounded-md"
          placeholder="원"
        />
      </div>

      {/* 추가 혜택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">추가 혜택</label>
        <div className="w-full border p-2 rounded-md bg-gray-50 text-sm whitespace-pre-wrap">
          {others || '선택된 요금제의 혜택 정보가 없습니다.'}
        </div>
      </div>

      {/* 할인 선택 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">할인 선택</label>
        <select
          name="discountType"
          value={values.discountType}
          onChange={e => onChange('discountType', e.target.value)}
          className="w-full border p-2 rounded-md"
        >
          <option value="">할인 없음</option>
          <option value="contract">요금할인 (25%)</option>
          <option value="subsidy">공시 지원금</option>
        </select>
        {recommendedDiscount && (
          <p className="mt-1 text-sm text-blue-600">
            추천 할인: {recommendedDiscount}
          </p>
        )}
      </div>

      {/* 공시 지원금 입력 */}
      {values.discountType === 'subsidy' && (
        <div className="mb-4">
          <label className="block text-sm font-medium mb-1">공시 지원금</label>
          <input
            type="number"
            name="subsidyAmount"
            value={values.subsidyAmount || ''}
            onChange={e => onChange('subsidyAmount', Number(e.target.value))}
            className="w-full border p-2 rounded-md"
            placeholder=" 공시 지원금"
          />
        </div>
      )}

      {/* 부분 수납 */}
      <div className="mb-4">
        <label className="block text-sm font-medium mb-1">부분 수납</label>
        <input
          type="number"
          name="partialPayment"
          value={values.partialPayment || ''}
          onChange={e => onChange('partialPayment', Number(e.target.value))}
          className="w-full border p-2 rounded-md"
          placeholder="부분 수납 입력"
        />
      </div>

      {/* 5G 시니어 카테고리일 때만 노출되는 기초연금 선택 */}
      {values.category === '5G 시니어 (만 65세 이상)' && (
        <div className="mb-4">
          <label className="block text-sm font-medium mb-1">
            기초연금 수급 여부
          </label>
          <select
            name="pensionApply"
            value={values.pensionApply }
            onChange={e => onChange('pensionApply', e.target.value)}
            className="w-full border p-2 rounded-md"
          >
            <option value="">— 선택하세요 —</option>
            <option value="yes">기초연금 수급 적용</option>
            <option value="no">기초연금 수급 미적용</option>
          </select>
        </div>
      )}

      {/* 할부개월 */}
      <div className="mb-6">
        <label className="block text-sm font-medium mb-1">할부개월</label>
        <select
          name="installments"
          value={values.installments}
          onChange={e => onChange('installments', Number(e.target.value))}
          className="w-full border p-2 rounded-md"
        >
          {[6, 12, 24, 36].map((n) => (
            <option key={n} value={n}>
              {n}개월
            </option>
          ))}
        </select>
      </div>
    </>
  );
}
